CREATE TABLE `dyski` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `producent` varchar(40) NOT NULL,
  `model` varchar(80) NOT NULL,
  `typ_dysku` varchar(10) NOT NULL COMMENT 'SSD lub HDD',
  `format` varchar(30) NOT NULL COMMENT 'M.2 2280, 2.5 cala, 3.5 cala',
  `interfejs` varchar(20) NOT NULL COMMENT 'NVMe, SATA III',
  `standard_pcie` decimal(2,1) DEFAULT NULL COMMENT '3.0, 4.0, 5.0 (NULL dla SATA)',
  `pojemnosc_gb` int(10) UNSIGNED NOT NULL,
  `predkosc_odczytu_mbs` int(10) UNSIGNED DEFAULT NULL,
  `predkosc_zapisu_mbs` int(10) UNSIGNED DEFAULT NULL,
  `klasa_wydajnosci` enum('S_flagowiec','A_wysoki','B_sredni','C_budzetowy','D_podstawowy') NOT NULL,
  `status_generacji` enum('aktualny','poprzednia_gen','archiwum') NOT NULL DEFAULT 'aktualny',
  `ocena_wydajnosci` tinyint(3) UNSIGNED NOT NULL COMMENT '1-100',
  `cena_pln` decimal(8,2) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_klasa` (`klasa_wydajnosci`,`status_generacji`),
  KEY `idx_ocena` (`ocena_wydajnosci`),
  KEY `idx_interfejs` (`interfejs`),
  KEY `idx_pojemnosc` (`pojemnosc_gb`),
  KEY `idx_cena` (`cena_pln`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


